&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bachelor’s degree in Economics, Econometrics, Finance,&amp;nbsp;Mathematics&amp;nbsp;or a closely related field from a top university (target GPA 3.7+).&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16053492,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;MBA&amp;nbsp;required;&amp;nbsp;Master’s&amp;nbsp;degree in Analytics, Data Science, Economics, or a related field a plus.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;5+ years of relevant experience&amp;nbsp;in&amp;nbsp;consulting,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;product management,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;data science&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, or strategy-oriented roles.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
